"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str

    @property
    def message(self) -> bytes:
        return crypto.canonical_message(self.sender, self.recipient, self.amount)

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        return {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
            "tx_id": self.tx_id,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import hmac
import json
import re

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def generate_private_key() -> str:
    """Generate a fresh Ed25519 private seed as 64 lowercase hex chars."""
    return Ed25519PrivateKey.generate().private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()


def derive_public_key(private_key_hex: str) -> str | None:
    """Derive the 64-hex Ed25519 public key from a 64-hex private seed.

    Returns None for malformed hex or a wrong-length seed rather than raising,
    so callers can treat every malformed key uniformly as a 400.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# Exact, ordered key sets of a batch Merkle-proof response document. They let
# verify_merkle_proof_bundle reject missing/extra keys *and* a wrong key order.
_BUNDLE_TOP_KEYS = ("height", "block_hash", "merkle_root", "transaction_ids", "proofs")
_BUNDLE_PROOF_KEYS = ("tx_id", "index", "siblings")
_BUNDLE_SIBLING_KEYS = ("direction", "hash")


def _exact_keys(value: object, keys: tuple[str, ...]) -> bool:
    """True iff ``value`` is a dict with exactly ``keys``, in that insertion order."""
    return isinstance(value, dict) and tuple(value.keys()) == keys


def verify_merkle_proof_bundle(
    bundle: object,
    expected_block_hash: object,
    expected_merkle_root: object,
) -> bool:
    """Strictly verify a batch Merkle-proof bundle offline.

    The bundle mirrors POST /v1/blocks/{height}/proofs::

        {"height": H, "block_hash": B, "merkle_root": R,
         "transaction_ids": [id, ...],     # ALL block leaves, ascending
         "proofs": [{"tx_id", "index", "siblings"}, ...]}  # requested subset

    ``transaction_ids`` is the block's complete, ascending leaf list; ``proofs``
    covers the requested tx_ids (a subset of it), itself sorted by tx_id. Every
    proof's leaf-to-root sibling path is re-hashed with the same pairing rules
    as :func:`merkle_root` (``sha256(left + right)`` hex pairs, a lone odd node
    paired with itself); the root is additionally recomputed directly from
    ``transaction_ids`` and must equal both the bundle's ``merkle_root`` and
    ``expected_merkle_root``, while ``block_hash`` must equal
    ``expected_block_hash``. Each proof ``index`` must be the tx_id's exact
    position in ``transaction_ids`` and its path must agree with that index at
    every level.

    Every defect — a missing/extra key, a wrong key order, a wrong type, a
    non-boolean/negative height, a duplicate/non-hex/non-string/unsorted tx_id,
    an unknown or duplicated proof tx_id, an out-of-range index, a path
    inconsistent with the index (including the phantom self-pair slot), an
    illegal direction or hash, excessive depth, an empty proof list, a tampered
    leaf list/root or block hash — returns False rather than raising.
    """
    try:
        if not _exact_keys(bundle, _BUNDLE_TOP_KEYS):
            return False
        if not _is_hex64(expected_block_hash) or not _is_hex64(expected_merkle_root):
            return False
        height = bundle["height"]
        block_hash = bundle["block_hash"]
        bundle_root = bundle["merkle_root"]
        transaction_ids = bundle["transaction_ids"]
        proofs = bundle["proofs"]

        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return False
        if not _is_hex64(block_hash):
            return False
        if not _is_hex64(bundle_root):
            return False
        if not isinstance(transaction_ids, list) or not transaction_ids:
            return False
        if not isinstance(proofs, list) or not proofs:
            return False
        if any(not _is_hex64(tx_id) for tx_id in transaction_ids):
            return False
        # Unique leaves ...
        if len(set(transaction_ids)) != len(transaction_ids):
            return False
        # ... in ascending tx_id order, matching the block's leaf ordering.
        if transaction_ids != sorted(transaction_ids):
            return False
        # The root is recomputed straight from the claimed leaf list, so the
        # list can never be tampered with independently of the paths.
        if not hmac.compare_digest(merkle_root(transaction_ids), bundle_root):
            return False

        positions = {tx_id: i for i, tx_id in enumerate(transaction_ids)}
        proof_ids: list[str] = []
        leaf_count = len(transaction_ids)
        for proof in proofs:
            if not _exact_keys(proof, _BUNDLE_PROOF_KEYS):
                return False
            tx_id = proof["tx_id"]
            index = proof["index"]
            siblings = proof["siblings"]
            if not _is_hex64(tx_id) or tx_id not in positions:
                return False
            if tx_id in proof_ids:
                return False
            if isinstance(index, bool) or not isinstance(index, int):
                return False
            # The index must be exactly the tx_id's leaf position; anything
            # else is a mismatch or out of range regardless of supplied hashes.
            if index != positions[tx_id] or not 0 <= index < leaf_count:
                return False
            if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
                return False

            # A depth-D path addresses one of 2**D leaf slots.
            depth = len(siblings)
            if index >= (1 << depth):
                return False
            current = tx_id
            position = index
            for item in siblings:
                if not _exact_keys(item, _BUNDLE_SIBLING_KEYS):
                    return False
                direction = item["direction"]
                sibling_hash = item["hash"]
                if not _is_hex64(sibling_hash):
                    return False
                # The odd-node promotion pairs the last (even-positioned) node
                # with a copy of itself, so a genuine self-pair always points
                # at a right sibling. A left sibling equal to the current node
                # addresses the phantom duplicate slot, which is never a real
                # leaf. The path must also agree with the index at every
                # level: an even position is the left child (sibling on its
                # right), an odd position the right child.
                if direction == "left":
                    if position % 2 == 0 or sibling_hash == current:
                        return False
                    pair = sibling_hash + current
                elif direction == "right":
                    if position % 2 == 1:
                        return False
                    pair = current + sibling_hash
                else:
                    return False
                current = sha256_hex(pair.encode("ascii"))
                position //= 2

            if not hmac.compare_digest(current, bundle_root):
                return False
            proof_ids.append(tx_id)

        # Proofs must be unique and ordered by tx_id ascending.
        if proof_ids != sorted(proof_ids):
            return False

        if not hmac.compare_digest(bundle_root, expected_merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# -- account state Merkle tree ----------------------------------------------


def account_state_leaf(
    account: str, balance: int, confirmed_transactions: list[str]
) -> str:
    """SHA-256 leaf of one account's confirmed state.

    The leaf is ``sha256(utf8(JSON))`` of the canonical compact JSON document
    ``{"account":a,"balance":b,"confirmed_transactions":T}`` serialized with
    ``sort_keys=True``, ``ensure_ascii=False`` and ``separators=(",",":")``.
    ``T`` keeps its original (on-chain) order; ``sort_keys`` only orders the
    three top-level keys.
    """
    document = {
        "account": account,
        "balance": balance,
        "confirmed_transactions": confirmed_transactions,
    }
    raw = json.dumps(
        document, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return sha256_hex(raw)


def account_state_root(leaves: list[str]) -> str:
    """Merkle root of account-state leaves ordered by ascending account.

    Uses the same pairing rules as :func:`merkle_root` (hex-string pairs
    hashed ``sha256(left + right)``, a lone odd node paired with itself); an
    empty account set has the same root as an empty tx list.
    """
    return merkle_root(leaves)


def verify_account_proof(
    proof: object,
    expected_root: object,
    expected_height: object,
    expected_hash: object,
) -> bool:
    """Verify an account-state Merkle proof offline.

    Recomputes the account leaf from
    ``{account, balance, confirmed_transactions}``, walks the leaf-to-root
    ``siblings`` path, and requires the recomputed root to equal both the
    proof's ``state_root`` and ``expected_root``, while ``height`` /
    ``block_hash`` anchor the tree to the expected confirmed tip. Every
    malformed input — a non-64-char lowercase hex hash or anchor, an illegal
    direction, an illegal index, a malformed leaf/balance/transaction list, a
    path inconsistent with the index, excessive depth — returns False rather
    than raising.
    """
    try:
        if not isinstance(proof, dict):
            return False
        account = proof.get("account")
        balance = proof.get("balance")
        transactions = proof.get("confirmed_transactions")
        index = proof.get("index")
        state_root = proof.get("state_root")
        height = proof.get("height")
        block_hash = proof.get("block_hash")
        siblings = proof.get("siblings")

        if not isinstance(account, str) or not account:
            return False
        if isinstance(balance, bool) or not isinstance(balance, int) or balance < 0:
            return False
        if not isinstance(transactions, list):
            return False
        if any(not _is_hex64(tx_id) for tx_id in transactions):
            return False
        if isinstance(index, bool) or not isinstance(index, int) or index < 0:
            return False
        if not isinstance(height, bool) and isinstance(height, int):
            if height < 0:
                return False
        else:
            return False
        if not _is_hex64(state_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_hash):
            return False
        if not _is_hex64(expected_root):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        # The leaf is always recomputed from the proof's own triple; a
        # client-supplied leaf value is never trusted.
        depth = len(siblings)
        # A depth-D path addresses one of 2**D leaf slots; a single-leaf tree
        # (D == 0) can only ever be index 0. An index outside that range is
        # illegal regardless of any hashes the caller supplies.
        if index >= (1 << depth):
            return False
        current = account_state_leaf(account, balance, transactions)
        position = index
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            # The odd-node promotion pairs the last (even-positioned) node
            # with a copy of itself, so a genuine self-pair always points at a
            # right sibling. A left sibling equal to the current node addresses
            # the phantom duplicate slot, which is never a real account.
            if direction == "left" and sibling_hash == current:
                return False
            # The path must agree with the index: at every level an even
            # position is the left child (sibling on its right) and an odd
            # position the right child.
            if direction == "left":
                if position % 2 == 0:
                    return False
                pair = sibling_hash + current
            elif direction == "right":
                if position % 2 == 1:
                    return False
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))
            position //= 2

        if not hmac.compare_digest(current, state_root):
            return False
        if not hmac.compare_digest(current, expected_root):
            return False
        if height != expected_height:
            return False
        if not hmac.compare_digest(block_hash, expected_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False

def mine_block(self) -> tuple[int, dict]:
    """Pack all pending transactions (ascending tx_id) into a pending block.

    Only allowed when the chain tip is confirmed; the new block becomes
    the pending tip until it is confirmed or rolled back.
    """
    with self.store.lock:
        if self.store.tip_is_pending():
            return 409, {"error": "tip block is pending confirmation"}
        if not self.store.pending:
            return 409, {"error": "no pending transactions"}
        ordered = sorted(self.store.pending.values(), key=lambda tx: tx.tx_id)
        block = Block.create(
            height=self.store.next_height(),
            prev_hash=self.store.tip_hash(),
            transactions=ordered,
            status=STATUS_PENDING,
        )
        self.store.chain.append(block)
        removed = [self.store.pending.pop(tx.tx_id) for tx in ordered]
        # First creation of this pending block: one block_mined event
        # carrying the block's ascending in-block transaction order.
        self.store.append_audit_event(
            EVENT_BLOCK_MINED,
            {
                "height": block.height,
                "block_hash": block.block_hash,
                "merkle_root": block.merkle_root,
                "transaction_ids": [tx.tx_id for tx in ordered],
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Undo the in-memory block and its event so nothing
            # un-persisted is visible.
            self.store.chain.pop()
            self.store.pending.update({tx.tx_id: tx for tx in removed})
            self.store.truncate_audit_events(1)
            raise
    return 201, {
        "height": block.height,
        "block_hash": block.block_hash,
        "merkle_root": block.merkle_root,
        "status": block.status,
    }

def get_block(self, height: object) -> tuple[int, dict]:
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        return 200, block.to_summary()

def get_block_status(self, height: object) -> tuple[int, dict]:
    """GET /v1/blocks/{height}/status -> {height, status}; 404 if unknown."""
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        return 200, {"height": block.height, "status": block.status}

def confirm_block(self, height: object) -> tuple[int, dict]:
    """Confirm a pending tip block.

    Only a pending chain tip whose parent is confirmed can be confirmed.
    Confirming an already-confirmed block is idempotent (200); every
    other case — unknown or malformed height, non-tip pending block —
    returns 409.
    """
    height_int = _parse_height(height)
    with self.store.lock:
        if height_int is None:
            return 409, {"error": "block cannot be confirmed"}
        block = self.store.block_at(height_int)
        if block is None:
            return 409, {"error": "block cannot be confirmed"}
        if block.status == STATUS_CONFIRMED:
            # Idempotent re-confirm.
            return 200, {"height": block.height, "status": STATUS_CONFIRMED}
        if block is not self.store.tip():
            return 409, {"error": "only the chain tip can be confirmed"}
        parent = self.store.chain[-2] if len(self.store.chain) >= 2 else None
        if parent is None or parent.status != STATUS_CONFIRMED:
            return 409, {"error": "previous block is not confirmed"}
        block.status = STATUS_CONFIRMED
        # First confirmation of the pending tip: one block_confirmed
        # event; the idempotent re-confirm above appends nothing.
        self.store.append_audit_event(
            EVENT_BLOCK_CONFIRMED,
            {"height": block.height, "block_hash": block.block_hash},
        )
        try:
            self.store.save()
        except BaseException:
            block.status = STATUS_PENDING
            self.store.truncate_audit_events(1)
            raise
        return 200, {"height": block.height, "status": STATUS_CONFIRMED}

def rollback_block(self, height: object) -> tuple[int, dict]:
    """Roll back a pending tip block: delete it and restore its transactions.

    Unknown or malformed heights (including an already-rolled-back
    height) return 404; a confirmed block or a non-tip block returns 409.
    """
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status == STATUS_CONFIRMED:
            return 409, {"error": "confirmed block cannot be rolled back"}
        if block is not self.store.tip():
            return 409, {"error": "only the chain tip can be rolled back"}
        pending_before = set(self.store.pending)
        rolled_back = self.store.rollback_tip()
        # Record exactly the transactions that actually returned to the
        # mempool (rollback_tip de-duplicates ids already present), in the
        # block's ascending in-block order.
        restored_ids = [
            tx.tx_id
            for tx in rolled_back.transactions
            if tx.tx_id not in pending_before
        ]
        self.store.append_audit_event(
            EVENT_BLOCK_ROLLED_BACK,
            {
                "height": rolled_back.height,
                "block_hash": rolled_back.block_hash,
                "transaction_ids": restored_ids,
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Restore the block and drop only the mempool entries we added.
            self.store.chain.append(rolled_back)
            for tx_id in list(self.store.pending):
                if tx_id not in pending_before:
                    del self.store.pending[tx_id]
            self.store.truncate_audit_events(1)
            raise
        return 200, {"height": rolled_back.height, "status": "rolled_back"}

def get_proof(self, height: object, tx_id: object) -> tuple[int, dict]:
    """Return a Merkle inclusion proof for tx_id at the given height.

    Returns 404 for an unknown height, a malformed height/tx_id, or a
    transaction absent from that block. Proofs are only issued for
    confirmed blocks; a pending block returns 409.
    """
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status != STATUS_CONFIRMED:
            return 409, {"error": "block is pending confirmation"}
        tx_ids = [tx.tx_id for tx in block.transactions]
        try:
            index = tx_ids.index(tx_id)
        except ValueError:
            return 404, {"error": "transaction not found"}
        siblings = crypto.merkle_proof(tx_ids, index)
        return 200, {
            "height": block.height,
            "tx_id": tx_id,
            "index": index,
            "merkle_root": block.merkle_root,
            "block_hash": block.block_hash,
            "siblings": siblings,
        }

def get_proofs(self, height: object, payload: object) -> tuple[int, dict]:
    """Return Merkle inclusion proofs for a batch of tx_ids at one height.

    POST /v1/blocks/{height}/proofs with ``{"tx_ids": [...]}``. The body
    must be a JSON object containing exactly the ``tx_ids`` key: a
    non-empty list of distinct 64-lowercase-hex strings. A malformed body
    — parse failure, missing/extra keys, a wrong type, an empty list,
    duplicates or a wrongly formatted id — is 400 and never touches state.
    A malformed/unknown height or any requested transaction absent from
    the block is 404; proofs are only issued for confirmed blocks, so a
    pending block returns 409.

    On success the body carries the block's complete ascending
    ``transaction_ids`` (every leaf) plus one
    ``{tx_id, index, siblings}`` proof per requested id, the proofs sorted
    by tx_id; the sibling paths run leaf-to-root exactly like
    :meth:`get_proof`.
    """
    if not isinstance(payload, dict) or set(payload) != {"tx_ids"}:
        return 400, {"error": "request body must be a JSON object with only 'tx_ids'"}
    tx_ids_raw = payload["tx_ids"]
    if not isinstance(tx_ids_raw, list) or not tx_ids_raw:
        return 400, {"error": "field 'tx_ids' must be a non-empty array"}
    if any(not crypto.is_hex64(tx_id) for tx_id in tx_ids_raw):
        return 400, {
            "error": "every tx_id must be a string of 64 lowercase hex characters"
        }
    if len(set(tx_ids_raw)) != len(tx_ids_raw):
        return 400, {"error": "tx_ids must be distinct"}

    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status != STATUS_CONFIRMED:
            return 409, {"error": "block is pending confirmation"}
        tx_ids = [tx.tx_id for tx in block.transactions]
        present = set(tx_ids)
        if any(tx_id not in present for tx_id in tx_ids_raw):
            return 404, {"error": "transaction not found"}
        requested = sorted(set(tx_ids_raw))
        proofs = []
        for tx_id in requested:
            index = tx_ids.index(tx_id)
            proofs.append({
                "tx_id": tx_id,
                "index": index,
                "siblings": crypto.merkle_proof(tx_ids, index),
            })
        return 200, {
            "height": block.height,
            "block_hash": block.block_hash,
            "merkle_root": block.merkle_root,
            "transaction_ids": tx_ids,
            "proofs": proofs,
        }

# -- accounts -----------------------------------------------------------

def get_account(self, account: str) -> tuple[int, dict]:
    with self.store.lock:
        entry = self.store.accounts.get(account)
        if entry is None:
            return 404, {"error": "account not found"}
        return 200, {
            "account": account,
            "balance": self.reported_balance(account),
            "confirmed_transactions": list(entry["transactions"]),
        }

# -- account state Merkle tree -------------------------------------------

def _state_tree(
    self, chain: list | None = None
) -> tuple[list[tuple[str, int, list[str]]], list[str], str]:
    """Build the confirmed account rows (ascending account), their leaves
    and the Merkle root, all from the confirmed chain under the current
    endowment. ``chain`` defaults to the whole canonical chain; a confirmed
    prefix replays historical state deterministically. Caller must hold the
    store lock.
    """
    if chain is None:
        chain = self.store.chain
    rows = self.store.account_state_rows(chain, self.initial_balance)
    leaves = [
        crypto.account_state_leaf(account, balance, transactions)
        for account, balance, transactions in rows
    ]
    return rows, leaves, crypto.account_state_root(leaves)

def get_state_root(self, height: object = None) -> tuple[int, dict]:
    """GET /v1/state/root and GET /v1/state/root/{height}.

    Without a height the tree is anchored to the highest block. A pending
    chain tip anchors nothing yet, so the endpoint returns 404 until the
    tip is confirmed.

    With a path height the state is replayed only from genesis through
    that block: the height must be an unsigned decimal without leading
    zeros (malformed heights are treated like any unknown path), the block
    must exist on the canonical chain and be confirmed — an unknown,
    non-canonical or pending height returns 404. The success body has
    exactly the same four fields as the unanchored endpoint.
    """
    with self.store.lock:
        if height is None:
            anchor = self.store.tip()
        else:
            # Strict unsigned decimal with no leading zeros, signs or
            # whitespace; every malformed value is an unknown path (404).
            height_int = _parse_decimal(height)

def tip(self) -> Block:
    return self.chain[-1]

def tip_hash(self) -> str:
    return self.chain[-1].block_hash

def next_height(self) -> int:
    return self.chain[-1].height + 1

def tip_is_pending(self) -> bool:
    return self.chain[-1].status == STATUS_PENDING

def block_at(self, height: int) -> Block | None:
    if 0 <= height < len(self.chain) and self.chain[height].height == height:
        return self.chain[height]
    return None

def rollback_tip(self) -> Block:
    """Remove the pending tip block and return its transactions to the mempool.

    Transactions are restored de-duplicated: an id already present in the
    pending set (resubmitted while the block was unconfirmed) is kept as
    is, not overwritten. Caller must hold the lock and must have checked
    that the tip is a pending block. Does not save; callers persist.
    """
    block = self.chain.pop()
    for tx in block.transactions:
        self.pending.setdefault(tx.tx_id, tx)
    return block

# -- fork candidates ------------------------------------------------------

@staticmethod
def _valid_tx_fields(tx: Transaction) -> None:
    """Structural checks shared by candidate submission and recovery."""
    if not isinstance(tx.sender, str) or not tx.sender:
        raise ValueError("transaction has an invalid 'from' field")
    if not isinstance(tx.recipient, str) or not tx.recipient:
        raise ValueError("transaction has an invalid 'to' field")
    if isinstance(tx.amount, bool) or not isinstance(tx.amount, int) or tx.amount <= 0:
        raise ValueError("transaction amount must be a positive integer")
    if not isinstance(tx.signature, str) or not tx.signature:
        raise ValueError("transaction is missing a signature")

def _parse_verified_chain(
    self, blocks_raw: object, endowment: int, genesis: Block | None = None
) -> list[Block]:
    """Strictly validate a block list submitted as (or persisted as) a fork.

    The list must start from the canonical genesis block, connect through
    consecutive heights and prev_hash values, and carry recomputed-correct
    Merkle roots and block hashes. Transactions must have valid Ed25519
    signatures, ascending and globally unique tx_ids, and a replay from the
    per-identity endowment must never overspend. All blocks must be
    confirmed except an optional pending tip. Raises ValueError on any
    defect.
    """
    if not isinstance(blocks_raw, list) or not blocks_raw:
        raise ValueError("'blocks' must be a non-empty list")
    genesis = genesis if genesis is not None else self.chain[0]
    blocks: list[Block] = []
    seen_tx_ids: set[str] = set()
    for i, block_raw in enumerate(blocks_raw):
        if not isinstance(block_raw, dict):
            raise ValueError(f"block at position {i} is not a JSON object")
        try:
            block = Block.from_dict(block_raw)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(f"block {i} is malformed: {exc}") from exc
        if isinstance(block.height, bool) or block.height != i:
            raise ValueError(
                f"block at position {i} has non-consecutive height {block.height}"
            )
        expected_prev = GENESIS_PREV_HASH if i == 0 else blocks[i - 1].block_hash
        if block.prev_hash != expected_prev:
            raise ValueError(f"block {i} has a mismatched prev_hash")
        if block.status not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise ValueError(f"block {i} has unknown status {block.status!r}")
        if i == 0:
            # The candidate must connect to *the* canonical genesis.
            if (
                block.status != STATUS_CONFIRMED
                or block.transactions
                or block.block_hash != genesis.block_hash
                or block.merkle_root != genesis.merkle_root
            ):
                raise ValueError("first block must be the canonical genesis block")
        elif i < len(blocks_raw) - 1 and block.status == STATUS_PENDING:
            raise ValueError(f"pending block {i} is not the chain tip")

        txs_raw = block_raw.get("transactions")
        if not isinstance(txs_raw, list):
            raise ValueError(f"block {i} transactions must be a list")
        tx_ids: list[str] = []
        for j, tx in enumerate(block.transactions):
            self._valid_tx_fields(tx)
            if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
                raise ValueError(f"block {i} transaction {j} has an invalid signature")
            stored_id = txs_raw[j].get("tx_id") if isinstance(txs_raw[j], dict) else None
            if stored_id != tx.tx_id:
                raise ValueError(
                    f"block {i} transaction {j} has a mismatched tx_id"
                )
            if tx.tx_id in seen_tx_ids:
                raise ValueError(f"duplicate transaction {tx.tx_id} in candidate")
            seen_tx_ids.add(tx.tx_id)
            tx_ids.append(tx.tx_id)
        if tx_ids != sorted(tx_ids):
            raise ValueError(f"block {i} transactions are not tx_id sorted")
        if crypto.merkle_root(tx_ids) != block.merkle_root:
            raise ValueError(f"block {i} Merkle root mismatch")
        if (
            compute_block_hash(block.height, block.prev_hash, block.merkle_root)
            != block.block_hash
        ):
            raise ValueError(f"block {i} block_hash mismatch")
        blocks.append(block)

    # Replay every transaction from the per-identity endowment; unconfirmed
    # (pending tip) transactions are included so a candidate can never hide
    # an overspend behind a pending final block.
    balances: dict[str, int] = {}
    for block in blocks:
        for tx in block.transactions:
            sender_balance = balances.get(tx.sender, endowment)
            if sender_balance < tx.amount:
                raise ValueError(
                    f"replay overspend by {tx.sender} in block {block.height}"
                )
            balances[tx.sender] = sender_balance - tx.amount
            balances[tx.recipient] = balances.get(tx.recipient, endowment) + tx.amount
    return blocks

def validate_fork_blocks(self, blocks_raw: object) -> list[Block]:
    """Validate and parse a candidate fork submitted by a client.

    The blocks must start from the canonical genesis block, connect via
    consecutive heights and prev_hash, carry correct block hashes and
    Merkle roots, unique ascending tx_ids with valid Ed25519 signatures and
    no replay overspend, and be all confirmed except an optional pending
    tip. Raises ValueError with a descriptive reason on any defect.
    """
    endowment = (
        self.initial_balance if self.initial_balance is not None else 1_000_000
    )
    return self._parse_verified_chain(blocks_raw, endowment)

@staticmethod
def validate_range_tail(anchor: dict, blocks_raw: object) -> list[Block]:
    """Strictly verify an incremental range's delivered tail standalone.

    Used both when a range delivery is first received and when range sync
    records are re-verified on restart; it never splices in (or depends on)
    the current canonical chain, so a same-key retry stays verifiable after
    the receiver's canonical chain has advanced. The tail must be a
    non-empty list of well-formed blocks whose heights start at
    ``anchor.height + 1`` and stay consecutive, whose first ``prev_hash``
    is the anchor hash (later ones linking internally), with
    recomputed-correct Merkle roots and block hashes, valid Ed25519
    signatures, tx_ids unique within the tail and ascending inside each
    block, and pending status only on its final block. Endowment replay is
    not part of this standalone check (it needs the canonical-prefix
    balances and is run on the assembled chain at first reception).
    Raises ValueError on any defect and returns the parsed tail Blocks.
    """
    if not isinstance(blocks_raw, list) or not blocks_raw:
        raise ValueError("'blocks' must be a non-empty list")
    tail: list[Block] = []
    seen_tx_ids: set[str] = set()
    expected_prev = anchor["block_hash"]
    for i, block_raw in enumerate(blocks_raw):
        if not isinstance(block_raw, dict):
            raise ValueError(f"block at position {i} is not a JSON object")
        try:
            block = Block.from_dict(block_raw)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(f"block {i} is malformed: {exc}") from exc
        expected_height = anchor["height"] + 1 + i
        if isinstance(block.height, bool) or block.height != expected_height:
            raise ValueError(
                f"block at position {i} has height {block.height}, "
                f"expected {expected_height}"
            )
        if block.prev_hash != expected_prev:
            raise ValueError(f"block {i} has a mismatched prev_hash")
        if block.status not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise ValueError(f"block {i} has unknown status {block.status!r}")
        if i < len(blocks_raw) - 1 and block.status == STATUS_PENDING:
            raise ValueError(f"pending block {i} is not the chain tip")
        txs_raw = block_raw.get("transactions")
        if not isinstance(txs_raw, list):
            raise ValueError(f"block {i} transactions must be a list")
        tx_ids: list[str] = []
        for j, tx in enumerate(block.transactions):
            LedgerStore._valid_tx_fields(tx)
            if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
                raise ValueError(
                    f"block {i} transaction {j} has an invalid signature"
                )
            stored_id = (
                txs_raw[j].get("tx_id") if isinstance(txs_raw[j], dict) else None
            )
            if stored_id != tx.tx_id:
                raise ValueError(
                    f"block {i} transaction {j} has a mismatched tx_id"
                )
            if tx.tx_id in seen_tx_ids:
                raise ValueError(
                    f"duplicate transaction {tx.tx_id} in range delivery"
                )
            seen_tx_ids.add(tx.tx_id)
            tx_ids.append(tx.tx_id)
        if tx_ids != sorted(tx_ids):
            raise ValueError(f"block {i} transactions are not tx_id sorted")
        if crypto.merkle_root(tx_ids) != block.merkle_root:
            raise ValueError(f"block {i} Merkle root mismatch")
        if (
            compute_block_hash(block.height, block.prev_hash, block.merkle_root)
            != block.block_hash
        ):
            raise ValueError(f"block {i} block_hash mismatch")
        expected_prev = block.block_hash
        tail.append(block)
    return tail

@staticmethod
def range_fingerprint(anchor: dict, tail: list[Block]) -> str:
    """SHA-256 content fingerprint of a delivered range (anchor + tail).

    Covers exactly what the sender delivered — never the assembled
    canonical prefix — so a same-key retry keeps matching after the
    receiver's canonical chain has advanced.
    """
    payload = {
        "anchor": {
            "height": anchor["height"],
            "block_hash": anchor["block_hash"],
        },
        "blocks": [block.to_dict() for block in tail],
    }
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, ensure_ascii=False).encode("utf-8")
    ).hexdigest()

def _parse_persisted_forks(
    self,
    forks_raw: object,
    canonical_chain: list[Block],
    endowment: int | None = None,
) -> dict[str, list[Block]]:
    """Parse persisted candidate forks, dropping invalid ones on restart.

    Every stored fork is re-validated exactly like a fresh submission
    (genesis connection, hashes, Merkle roots, signatures, uniqueness,
    replay). A fork that no longer validates is silently discarded rather
    than failing recovery of the canonical chain. Recovery of the canonical
    chain itself remains strict and still raises StateRecoveryError. The
    replay uses ``endowment`` — the value recorded in this snapshot — rather
    than the startup argument, so a different launch parameter cannot make
    a persisted fork legal or illegal.
    """
    if not isinstance(forks_raw, list):
        return {}
    if endowment is None:
        endowment = DEFAULT_INITIAL_BALANCE
    genesis = canonical_chain[0]
    forks: dict[str, list[Block]] = {}
    for entry in forks_raw:
        try:
            fork = self._parse_verified_chain(entry, endowment, genesis)
        except (ValueError, KeyError, TypeError):
            continue
        if not fork or fork[0].block_hash != genesis.block_hash:
            continue
        tip_hash = fork[-1].block_hash
        # The canonical chain (or a strict prefix of it, matched by any
        # canonical block hash) is never also stored as a candidate.
        if any(tip_hash == block.block_hash for block in canonical_chain):
            continue
        forks.setdefault(tip_hash, fork)
    return forks

def replace_chain(self, new_chain: list[Block]) -> None:
    """Atomically adopt a fork: swap the canonical chain, reconcile the
    mempool (old-chain-only confirmed transactions return de-duplicated;
    pending-block transactions never enter the pool) and rebuild indexes.
    Does not save; the caller persists.
    """
    old_confirmed_ids = {
        tx.tx_id
        for block in self.chain
        if block.status == STATUS_CONFIRMED
        for tx in block.transactions
    }
    new_ids = {tx.tx_id for block in new_chain for tx in block.transactions}
    old_tx_by_id = {
        tx.tx_id: tx
        for block in self.chain
        for tx in block.transactions
    }

def confirmed_balance(self, account: str) -> int:
    """Balance from confirmed blocks only."""
    entry = self.store.accounts.get(account)
    if entry is None:
        return self.initial_balance
    return self.initial_balance + entry["received"] - entry["sent"]

def reported_balance(self, account: str) -> int:
    """Confirmed balance minus spends sitting in the pending tip block.

    Pending-block credits are not counted: unconfirmed income can still
    be rolled back, so it must not inflate the reported balance.
    """
    balance = self.confirmed_balance(account)
    tip = self.store.tip()
    if tip.status == STATUS_PENDING:
        for tx in tip.transactions:
            if tx.sender == account:
                balance -= tx.amount
    return balance

def available_balance(self, account: str) -> int:
    """Reported balance minus amounts already committed in the mempool.

    Pending credits (mempool or unconfirmed block) are deliberately not
    counted, so a sequence of submissions cannot spend money that has not
    been confirmed yet.
    """
    balance = self.reported_balance(account)
    for tx in self.store.pending.values():
        if tx.sender == account:
            balance -= tx.amount
    return balance

# -- fork candidates -----------------------------------------------------

@staticmethod
def _fork_summary(blocks: list) -> dict:
    """Public fork descriptor S: tip_hash, height, length, status."""
    tip = blocks[-1]
    return {
        "tip_hash": tip.block_hash,
        "height": tip.height,
        # The length counts every block including the genesis block.
        "length": len(blocks),
        "status": tip.status,
    }

def _winning_fork(self) -> tuple[str, list]:
    """Pick the winner among the canonical chain and every candidate.

    Longest chain wins; equal lengths are broken by the smallest tip hash
    (lexicographic hex order). Returns (tip_hash, block list).
    """
    contenders: list[tuple[str, list]] = [
        (self.store.tip_hash(), self.store.chain)
    ]
    contenders.extend(self.store.forks.items())
    contenders.sort(key=lambda item: (-len(item[1]), item[0]))
    return contenders[0]

def submit_fork_candidate(self, payload: object) -> tuple[int, dict]:
    """POST /v1/forks/candidates — validate and store a candidate fork.

    Returns 201 with the fork descriptor S. Malformed or invalid forks
    return 400; a fork already known (identical to the canonical tip or an
    existing candidate tip) returns 409.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    blocks_raw = payload.get("blocks")
    if not isinstance(blocks_raw, list):
        return 400, {"error": "missing field: blocks (must be a list)"}
    try:
        fork = self.store.validate_fork_blocks(blocks_raw)
    except ValueError as exc:
        return 400, {"error": str(exc)}
    summary = self._fork_summary(fork)
    # An exported fork (the five-field {tip_hash, height, length, status,
    # blocks} document) may be resubmitted verbatim; every supplied summary
    # field is re-verified against the recomputed descriptor.
    for field in ("tip_hash", "height", "length", "status"):
        if field in payload and payload[field] != summary[field]:
            return 400, {"error": f"summary field {field!r} does not match the blocks"}
    tip_hash = fork[-1].block_hash
    with self.store.lock:
        self._prune_expired_syncs()
        # A tip hash equal to any canonical block hash means the candidate
        # is exactly the canonical chain or a prefix of it (the block hash
        # binds height, parent and Merkle root), so it carries nothing new.
        if any(tip_hash == block.block_hash for block in self.store.chain):
            return 409, {"error": "fork is identical to the canonical chain"}
        if tip_hash in self.store.forks:
            return 409, {"error": "candidate fork already exists", "tip_hash": tip_hash}
        self.store.forks[tip_hash] = fork
        try:
            self.store.save()
        except BaseException:
            self.store.forks.pop(tip_hash, None)
            raise
    return 201, self._fork_summary(fork)

def get_chain(self) -> tuple[int, dict]:
    """GET /v1/chain — canonical chain, candidates sorted by tip hash and
    the adoptable winner (a non-canonical chain that beats canonical).
    """
    with self.store.lock:
        self._prune_expired_syncs()
        canonical = self._fork_summary(self.store.chain)
        candidates = [
            self._fork_summary(self.store.forks[tip])
            for tip in sorted(self.store.forks)
        ]
        winner_tip, winner_chain = self._winning_fork()
        adoptable: list[dict] = []
        if winner_tip != self.store.tip_hash():
            adoptable.append(self._fork_summary(winner_chain))
        return 200, {
            "canonical": canonical,
            "candidates": candidates,
            "adoptable": adoptable,
        }

def adopt_fork(self, tip_hash: object) -> tuple[int, dict]:
    """POST /v1/forks/{tip_hash}/adopt — atomically switch to the winner.

    Unknown tips return 404; adopting anything other than the current
    winning (longest / smallest-tip-hash) chain returns 409. Adoption
    replaces the canonical chain and mempool in one atomic write that
    advances the generation and rebuilds all indexes; transactions unique
    to the old chain's confirmed history return to the mempool, while
    pending-block transactions never enter it.
    """
    if not crypto.is_hex64(tip_hash):
        return 404, {"error": "unknown fork tip"}
    with self.store.lock:
        self._prune_expired_syncs()
        fork = self.store.forks.get(tip_hash)
        if fork is None:
            return 404, {"error": "unknown fork tip"}
        winner_tip, _ = self._winning_fork()
        if winner_tip != tip_hash:
            return 409, {"error": "only the winning fork can be adopted"}
        old_chain = self.store.chain
        old_pending = dict(self.store.pending)
        self.store.forks.pop(tip_hash)
        self.store.replace_chain(fork)
        # An adopted synced tip keeps its sync records (queryable until
        # expiry); record the adoption once per provenance entry. The
        # adopted tip summary is frozen from the adopted fork itself and
        # is never rewritten by later expiry.
        adopted_summary = self._fork_summary(fork)
        # The adopted tip may have provenance entries in the plain table,
        # the attested table, or both; each gets one adoption event.
        adopted: list[tuple[str | None, tuple[str, str]]] = []
        for skey in sorted(self.store.syncs):
            if self.store.syncs[skey]["tip_hash"] == tip_hash:
                adopted.append((None, skey))
        for skey in sorted(self.store.attested_syncs):
            if self.store.attested_syncs[skey]["tip_hash"] == tip_hash:
                adopted.append((SYNC_MODE_ATTESTED, skey))
        adopted_count = len(adopted)
        for rec_mode, (rec_source, request_id) in adopted:
            table = (
                self.store.attested_syncs
                if rec_mode is not None
                else self.store.syncs
            )
            payload = {
                "source": rec_source,
                "request_id": request_id,
                "tip_hash": tip_hash,
                "expires_at": table[(rec_source, request_id)]["expires_at"],
                "height": adopted_summary["height"],
                "length": adopted_summary["length"],
                "status": adopted_summary["status"],
            }
            if rec_mode is not None:
                payload["mode"] = rec_mode
            self.store.append_audit_event(EVENT_SYNC_ADOPTED, payload)
        try:
            self.store.save()
        except BaseException:
            # Restore the pre-adoption in-memory state on a failed write.
            self.store.chain = old_chain
            self.store.pending = old_pending
            self.store.forks[tip_hash] = fork
            self.store.rebuild_derived()
            self.store.truncate_audit_events(adopted_count)
            raise
        return 200, self._fork_summary(fork)

def export_fork(self, tip_hash: object) -> tuple[int, dict]:
    """GET /v1/forks/{tip_hash}/export — full export of a candidate fork.

    Only stored candidates are exportable: the canonical tip, an unknown
    tip and a malformed tip hash (not 64 lowercase hex chars) all return
    404. The response carries exactly five fields — the fork descriptor
    (tip_hash, height, length, status, all describing the tip block) plus
    the full block list including the genesis block, every transaction's
    signature and an optional pending tip — and can be resubmitted to
    POST /v1/forks/candidates verbatim.
    """
    if not crypto.is_hex64(tip_hash):
        return 404, {"error": "unknown fork tip"}
    with self.store.lock:
        fork = self.store.forks.get(tip_hash)
        if fork is None:
            return 404, {"error": "unknown fork tip"}
        body = self._fork_summary(fork)
        body["blocks"] = [block.to_dict() for block in fork]
        return 200, body

# -- incremental chain ranges --------------------------------------------

RANGE_DEFAULT_LIMIT = 100
RANGE_MAX_LIMIT = 500

@staticmethod
def _anchor_descriptor(block: Block) -> dict:
    """Public range anchor shape: {height, block_hash}."""
    return {"height": block.height, "block_hash": block.block_hash}

def get_chain_range(self, params: dict) -> tuple[int, dict]:
    """GET /v1/chain/range — the canonical blocks strictly after an anchor.

    Query parameters: ``after_height`` (a non-negative decimal anchor
    height) and ``after_hash`` (the anchor block's hash, 64 lowercase hex
    characters), both required, plus ``limit`` (default 100, range 1-500).
    Every value must follow the strict decimal/hex format used by the

def _parse_persisted_audit_events(raw: object, path: str) -> list[dict]:
    """Strictly parse the append-only audit event log.

    Every event is a JSON object carrying an integer ``at`` timestamp and a
    string ``kind``; ``event_id`` values must be exactly 1..N with no gaps
    or duplicates, since the id is the event's permanent audit position
    (which also fixes the log's total ordering). Payload fields beyond
    those three are retained verbatim.

    The historical sync lifecycle events additionally have their provenance
    metadata validated: ``sync_received`` / ``sync_adopted`` /
    ``sync_expired`` must carry a non-empty ``source`` and ``request_id``
    and a 64-char lowercase hex ``tip_hash``; an ``expires_at`` and the
    frozen tip summary (``height`` / ``length`` / ``status``) are checked
    when present — older snapshots' adopted events predate those fields, so
    missing ones are accepted but malformed ones are corruption. The
    keyless-allowlist events ``allowlist_added`` / ``allowlist_removed``
    likewise require a non-empty ``source`` and an integer
    ``expires_at``.
    """
    if raw is None:
        return []
    if not isinstance(raw, list):
        raise StateRecoveryError(path, "'audit_events' must be a list")
    sync_kinds = {
        EVENT_SYNC_RECEIVED,
        EVENT_SYNC_ADOPTED,
        EVENT_SYNC_EXPIRED,
    }
    allowlist_kinds = {
        EVENT_ALLOWLIST_ADDED,
        EVENT_ALLOWLIST_REMOVED,
    }
    # The node-managed checkpoint-history endpoints append history_access
    # events carrying the action and the heads the two external files had
    # at access time (64-hex, or null when the file did not exist yet).
    history_access_kinds = {EVENT_HISTORY_ACCESS}
    # The four core ledger lifecycle events carry strictly typed,
    # exact-key-set payloads; their inter-event state machine and the
    # facts they reference are cross-checked separately by
    # _validate_ledger_lifecycle_events once the whole chain is parsed.
    ledger_event_payload_keys = {
        EVENT_TRANSACTION_SUBMITTED: (
            "tx_id",
            "from",
            "to",
            "amount",
        ),
        EVENT_BLOCK_MINED: (
            "height",
            "block_hash",
            "merkle_root",
            "transaction_ids",
        ),
        EVENT_BLOCK_CONFIRMED: ("height", "block_hash"),
        EVENT_BLOCK_ROLLED_BACK: (
            "height",
            "block_hash",
            "transaction_ids",
        ),
    }
    ledger_event_kinds = set(ledger_event_payload_keys)
    events: list[dict] = []
    for i, event in enumerate(raw):
        if not isinstance(event, dict):
            raise StateRecoveryError(path, f"audit event {i + 1} must be an object")
        event_id = event.get("event_id")
        kind = event.get("kind")
        at = event.get("at")
        if (
            isinstance(event_id, bool)
            or not isinstance(event_id, int)
            or event_id != i + 1
        ):
            raise StateRecoveryError(
                path,
                f"audit event at position {i} has event_id {event_id!r}, "
                f"expected {i + 1}",
            )
        if not isinstance(kind, str) or not kind:
            raise StateRecoveryError(path, f"audit event {event_id} needs a kind")
        if isinstance(at, bool) or not isinstance(at, (int, float)):
            raise StateRecoveryError(path, f"audit event {event_id} needs a numeric 'at'")
        if kind in sync_kinds:
            source = event.get("source")
            request_id = event.get("request_id")
            tip_hash = event.get("tip_hash")
            if not isinstance(source, str) or not source:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a source"
                )
            if not isinstance(request_id, str) or not request_id:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a request_id"
                )
            if not crypto.is_hex64(tip_hash):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid tip_hash"
                )
            expires_at = event.get("expires_at")
            if expires_at is not None and (
                isinstance(expires_at, bool) or not isinstance(expires_at, int)
            ):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) expires_at must be an integer",
                )
            height = event.get("height")
            if height is not None and (
                isinstance(height, bool) or not isinstance(height, int) or height < 0
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid height"
                )
            length = event.get("length")
            if length is not None and (
                isinstance(length, bool) or not isinstance(length, int) or length < 1
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has an invalid length"
                )
            status = event.get("status")
            if status is not None and status not in (
                STATUS_PENDING,
                STATUS_CONFIRMED,
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has invalid status"
                )
            # The three frozen summary fields travel together: a partially
            # frozen event is an inconsistent write and is corruption.
            summary_fields = (height, length, status)
            if any(field is not None for field in summary_fields) and any(
                field is None for field in summary_fields
            ):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) has a partial frozen summary",
                )
            # The attested-sync feature adds an optional mode; when present
            # it must be a recognized delivery mode.
            mode = event.get("mode")
            if mode is not None and mode not in (
                SYNC_MODE_PLAIN,
                SYNC_MODE_ATTESTED,
            ):
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) has invalid mode"
                )
        elif kind in allowlist_kinds:
            # The keyless allowlist is authoritative configuration (exactly
            # like trust_sources): an allowlist_added/removed event must
            # carry a non-empty ``source`` and a plain (non-boolean)
            # integer ``expires_at``. A malformed payload is snapshot
            # corruption and fails recovery rather than loading.
            source = event.get("source")
            expires_at = event.get("expires_at")
            if not isinstance(source, str) or not source:
                raise StateRecoveryError(
                    path, f"audit event {event_id} ({kind}) needs a source"
                )
            if isinstance(expires_at, bool) or not isinstance(expires_at, int):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) expires_at must be an integer",
                )
        elif kind in history_access_kinds:
            # history_access events bind the audit log to the node-managed
            # checkpoint-history files: action is read/update/export and
            # both heads must be present as either 64-char lowercase hex
            # or JSON null (the referenced file did not exist yet).
            action = event.get("action")
            if action not in ("read", "update", "export"):
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) has an invalid action",
                )
            for head_field in ("trust_head", "history_head"):
                if head_field not in event:
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} ({kind}) is missing "
                        f"{head_field}",
                    )
                head = event[head_field]
                if head is not None and not crypto.is_hex64(head):
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} ({kind}) {head_field} "
                        "must be 64 lowercase hex characters or null",
                    )
        elif kind in ledger_event_kinds:
            # The lifecycle event must carry exactly its documented
            # payload keys in addition to the five chain fields
            # (event_id, kind, at, prev_hash, event_hash).
            expected_payload = ledger_event_payload_keys[kind]
            allowed = set(expected_payload) | {
                "event_id",
                "kind",
                "at",
                "prev_hash",
                "event_hash",
            }
            if set(event) != allowed:
                raise StateRecoveryError(
                    path,
                    f"audit event {event_id} ({kind}) must carry exactly "
                    f"the payload keys {', '.join(expected_payload)}",
                )
            if kind == EVENT_TRANSACTION_SUBMITTED:
                tx_id = event["tx_id"]
                sender = event["from"]
                recipient = event["to"]
                amount = event["amount"]
                if not crypto.is_hex64(tx_id):
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} (transaction_submitted) "
                        "tx_id must be 64 lowercase hex characters",
                    )
                if not isinstance(sender, str) or not sender:
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} (transaction_submitted) "
                        "'from' must be a non-empty string",
                    )
                if not isinstance(recipient, str) or not recipient:
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} (transaction_submitted) "
                        "'to' must be a non-empty string",
                    )
                if (
                    isinstance(amount, bool)
                    or not isinstance(amount, int)
                    or amount <= 0
                ):
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} (transaction_submitted) "
                        "amount must be a positive integer",
                    )
            else:
                height = event["height"]
                block_hash = event["block_hash"]
                if isinstance(height, bool) or not isinstance(height, int) or height < 1:
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} ({kind}) height must be a "
                        "positive integer",
                    )
                if not crypto.is_hex64(block_hash):
                    raise StateRecoveryError(
                        path,
                        f"audit event {event_id} ({kind}) block_hash must "
                        "be 64 lowercase hex characters",
                    )
                if kind == EVENT_BLOCK_MINED:
                    merkle_root = event["merkle_root"]
                    if not crypto.is_hex64(merkle_root):
                        raise StateRecoveryError(
                            path,
                            f"audit event {event_id} (block_mined) "
                            "merkle_root must be 64 lowercase hex characters",
                        )
                tx_ids = event.get("transaction_ids")
                if tx_ids is not None:
                    # A core-mined block always packs at least one
                    # transaction; a rolled-back adopted fork tip may
                    # carry none, so the empty list is only legal on
                    # block_rolled_back.
                    if not isinstance(tx_ids, list):
                        raise StateRecoveryError(
                            path,
                            f"audit event {event_id} ({kind}) "
                            "transaction_ids must be a list",
                        )
                    if kind == EVENT_BLOCK_MINED and not tx_ids:
                        raise StateRecoveryError(
                            path,
                            f"audit event {event_id} (block_mined) "
                            "transaction_ids must be a non-empty list",
                        )
                    if any(not crypto.is_hex64(value) for value in tx_ids):
                        raise StateRecoveryError(
                            path,
                            f"audit event {event_id} ({kind}) every "
                            "transaction id must be 64 lowercase hex "
                            "characters",
                        )
                    if len(set(tx_ids)) != len(tx_ids) or tx_ids != sorted(tx_ids):
                        raise StateRecoveryError(
                            path,
                            f"audit event {event_id} ({kind}) "
                            "transaction_ids must be distinct and "
                            "ascending in block order",
                        )
        events.append(dict(event))
    return events

def submit_fork_sync_range(self, payload: object) -> tuple[int, dict]:
    """POST /v1/forks/sync/range — receive an incremental chain range.

    The request carries ``source``, ``request_id``, ``expires_at`` (Unix
    seconds), ``anchor`` (``{height, block_hash}`` naming the canonical
    block the range starts *after*), ``blocks`` (a non-empty list of
    complete blocks starting at the next height) and ``tip`` (the
    mandatory closed summary ``{tip_hash, height, length, status}`` of the
    delivered chain: exactly those four fields, a 64-hex tip_hash, a
    non-boolean non-negative height, a non-boolean positive length and a
    pending/confirmed status). Any structural, type or summary violation
    is 400, decided BEFORE the source is authorized and before any
    candidate, fork, sync record, audit event or generation is touched.

    A new request follows the full-sync order: envelope format validation
    (400), then the source authorization gate (403), then the request
    deadline (410). The anchor must then match the *current* canonical
    chain: an unknown anchor height or a hash mismatch is a stale anchor
    (409). The tail is prepended with the canonical prefix and put through
    the existing whole-chain re-validation (genesis connection,
    consecutive heights/prev_hash, recomputed block hashes and Merkle
    roots, tx_id/Ed25519 verification, global uniqueness and ordering,
    endowment replay, pending-only-at-tip); failure is 400, as is a
    ``tip`` summary that does not recompute (height must equal the last
    block's height, length the assembled chain length including genesis,
    status the last block's status). A tip already known as the
    canonical chain or a stored candidate is 409, mirroring full sync.

    Success stores the ASSEMBLED complete candidate (keyed by its tip hash)
    together with the sync record, the range content fingerprint
    (anchor + delivered tail only) and a ``sync_received`` event in one
    atomic write; 201 returns the same five fields as a full sync. A
    same-key retry on a live record first re-validates anchor, blocks and
    the full tip STANDALONE (never re-spliced against the current
    canonical chain): a malformed or tampered body fails 400 rather than
    replaying the cached 200, identical content replays the original
    frozen result as 200 with its original ``expires_at``, and any other
    well-formed content conflicts 409. The replay is unaffected by the
    source having rotated/revoked/expired, by the request deadline having
    passed, or by the receiver's canonical chain having advanced.
    Longest-chain adoption, expiry, mempool return-to-pool and restart
    reconciliation then all operate on the stored assembled candidate
    exactly as for a full sync.
    """
    if not isinstance(payload, dict):
        return 400, {"error": "request body must be a JSON object"}
    for field in ("source", "request_id", "expires_at", "anchor", "blocks", "tip"):
        if field not in payload:
            return 400, {"error": f"missing field: {field}"}

    source = payload["source"]
    request_id = payload["request_id"]
    expires_at = payload["expires_at"]
    anchor_raw = payload["anchor"]
    blocks_raw = payload["blocks"]
    tip = payload["tip"]

    if not isinstance(source, str) or not source:
        return 400, {"error": "field 'source' must be a non-empty string"}
    if not isinstance(request_id, str) or not request_id:
        return 400, {"error": "field 'request_id' must be a non-empty string"}
    if isinstance(expires_at, bool) or not isinstance(expires_at, int):
        return 400, {"error": "field 'expires_at' must be a Unix-seconds integer"}
    if not isinstance(anchor_raw, dict):
        return 400, {"error": "field 'anchor' must be a JSON object"}
    anchor_height = anchor_raw.get("height")
    anchor_hash = anchor_raw.get("block_hash")
    if (
        isinstance(anchor_height, bool)
        or not isinstance(anchor_height, int)
        or anchor_height < 0
    ):
        return 400, {"error": "anchor.height must be a non-negative integer"}
    if not crypto.is_hex64(anchor_hash):
        return 400, {
            "error": "anchor.block_hash must be 64 lowercase hex characters"
        }
    anchor = {"height": anchor_height, "block_hash": anchor_hash}
    if not isinstance(blocks_raw, list):
        return 400, {"error": "field 'blocks' must be a list"}
    if not blocks_raw:
        return 400, {"error": "field 'blocks' must be non-empty"}
    # The tip summary is mandatory and closed: exactly the four fields
    # tip_hash/height/length/status, each strictly typed. Any structural
    # or type violation is 400 here, before the source is authorized and
    # before any candidate, fork, sync record, audit event or generation
    # is touched.
    if not isinstance(tip, dict):
        return 400, {"error": "field 'tip' must be a JSON object"}
    if set(tip) != {"tip_hash", "height", "length", "status"}:
        return 400, {
            "error": "tip must contain exactly tip_hash, height, length and status"
        }
    if not crypto.is_hex64(tip["tip_hash"]):
        return 400, {"error": "tip.tip_hash must be 64 lowercase hex characters"}
    if (
        isinstance(tip["height"], bool)
        or not isinstance(tip["height"], int)
        or tip["height"] < 0
    ):
        return 400, {"error": "tip.height must be a non-negative integer"}
    if (
        isinstance(tip["length"], bool)
        or not isinstance(tip["length"], int)
        or tip["length"] < 1
    ):
        return 400, {"error": "tip.length must be a positive integer"}
    if tip["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
        return 400, {"error": "tip.status must be 'pending' or 'confirmed'"}

    with self.store.lock:
        self._prune_expired_syncs()
        key = (source, request_id)
        existing = self.store.syncs.get(key)

        if existing is not None:
            # Idempotent replay on a live key. The tail is re-verified
            # STANDALONE (never re-spliced against the current canonical
            # chain) and its supplied tip summary recomputed BEFORE the
            # idempotency decision — exactly like a full-sync retry, where
            # a malformed/tampered body fails 400 rather than replaying the
            # cached 200. Identical range content then replays the original
            # frozen result as 200 even after the source has rotated,
            # revoked or expired OR the receiver's canonical chain has
            # advanced; changed content conflicts 409. The authorization
            # gate is bypassed for retries.
            try:
                tail = self.store.validate_range_tail(anchor, blocks_raw)
            except ValueError as exc:
                return 400, {"error": str(exc)}
            recomputed_tip = self._range_tip_summary(anchor, tail)
            if tip != recomputed_tip:
                return 400, {"error": "tip summary does not match the blocks"}
            fingerprint = self.store.range_fingerprint(anchor, tail)
            if fingerprint != existing["fingerprint"]:
                return 409, {
                    "error": "request_id already used with different content"
                }
            descriptor = None
            if existing.get("height") is not None:
                descriptor = {
                    "tip_hash": existing["tip_hash"],
                    "height": existing["height"],
                    "length": existing["length"],
                    "status": existing["status"],
                }
            if descriptor is None:
                descriptor = self._tip_descriptor(existing["tip_hash"]) or {
                    "tip_hash": existing["tip_hash"],
                    "height": None,
                    "length": None,
                    "status": None,
                }
            return 200, {
                "tip_hash": descriptor["tip_hash"],
                "height": descriptor.get("height"),
                "length": descriptor.get("length"),
                "status": descriptor.get("status"),
                "expires_at": existing["expires_at"],
            }

        # New delivery follows the full-sync order: authorization (403),
        # then the request deadline (410), before the anchor or chain is
        # examined.
        now = time.time()
        trusted = self.store.trust_sources.get(source)
        if (
            trusted is None
            or trusted["status"] != TRUST_ACTIVE
            or trusted["expires_at"] <= now
        ):
            return 403, {"error": "source is not an active trusted source"}
        if expires_at <= now:
            return 410, {"error": "sync request has expired"}

        # The anchor must match the current canonical chain; an unknown
        # height or a mismatched hash is a stale anchor (409).
        anchor_block = self.store.block_at(anchor_height)
        if anchor_block is None or anchor_block.block_hash != anchor_hash:
            return 409, {"error": "anchor does not match the current canonical chain"}

        # Splice the canonical prefix and run the existing whole-chain
        # revalidation: blocks start at the next height and stay
        # consecutive, prev_hash links onto the anchor, recomputed block
        # hashes/Merkle roots, tx_id/Ed25519 verification, global
        # uniqueness and block ordering, endowment replay, and
        # pending-only-at-tip. Failure is 400.
        assembled_raw = [
            block.to_dict() for block in self.store.chain[: anchor_height + 1]
        ]
        assembled_raw.extend(
            block_raw for block_raw in blocks_raw
        )
        try:
            fork = self.store.validate_fork_blocks(assembled_raw)
        except ValueError as exc:
            return 400, {"error": str(exc)}
        summary = self._fork_summary(fork)
        tail = fork[anchor_height + 1 :]
        recomputed_tip = self._range_tip_summary(anchor, tail)
        if summary != recomputed_tip:
            return 400, {"error": "range does not assemble onto the canonical chain"}
        if tip != recomputed_tip:
            return 400, {"error": "tip summary does not match the blocks"}
        fingerprint = self.store.range_fingerprint(anchor, tail)
        tip_hash = fork[-1].block_hash

        if any(tip_hash == block.block_hash for block in self.store.chain):
            return 409, {"error": "fork is identical to the canonical chain"}
        if tip_hash in self.store.forks:
            return 409, {
                "error": "candidate fork already exists",
                "tip_hash": tip_hash,
            }

        # Persist the ASSEMBLED candidate so adoption, expiry cleanup and
        # restart never need to re-splice it against a later canonical,
        # alongside the range payload and its range-content fingerprint.
        self.store.forks[tip_hash] = fork
        self.store.syncs[key] = {
            "tip_hash": tip_hash,
            "expires_at": expires_at,
            "fingerprint": fingerprint,
            "height": summary["height"],
            "length": summary["length"],
            "status": summary["status"],
            "range": {
                "anchor": dict(anchor),
                "blocks": [block.to_dict() for block in tail],
            },
        }
        self.store.append_audit_event(
            EVENT_SYNC_RECEIVED,
            {
                "source": source,
                "request_id": request_id,
                "tip_hash": tip_hash,
                "expires_at": expires_at,
                "height": summary["height"],
                "length": summary["length"],
                "status": summary["status"],
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Roll back the assembled candidate, its range record and the
            # audit event together: a failed write changes nothing.
            self.store.syncs.pop(key, None)
            self.store.forks.pop(tip_hash, None)
            self.store.truncate_audit_events(1)
            raise

        result = dict(summary)
        result["expires_at"] = expires_at
        return 201, result

